import java.util.Random;

public class DiceRoller {

    public static int rollSum(long seed, int times) {
        Random random = new Random(seed);
        int sum = 0;
        for (int i = 0; i < times; i++) {
            sum += random.nextInt(6) + 1;
        }
        return sum;
    }
}
